function migrateDb(source){db=source;db.schemaVersion=SCHEMA_VERSION;db.rentals=Array.isArray(db.rentals)?db.rentals:[];db.rentalsArchive=Array.isArray(db.rentalsArchive)?db.rentalsArchive:[];/* UTILISATEURS - début */db.users=Array.isArray(db.users)?db.users:[];/* UTILISATEURS - fin *//* PAIE - début */if(!db.paie||typeof db.paie!=='object')db.paie={};db.paie.salaries=Array.isArray(db.paie.salaries)?db.paie.salaries:[{id:'sal-demo-001',name:'Yanis Benali',matricule:'CH-001',activity:['NEXTDAY'],status:'active',phone:'',email:'',createdAt:'2026-11-03T00:00:00.000Z'},{id:'sal-demo-002',name:'Moussa Diallo',matricule:'CH-002',activity:['SAMEDAY'],status:'active',phone:'',email:'',createdAt:'2026-11-03T00:00:00.000Z'},{id:'sal-demo-003',name:'Karim Haddad',matricule:'CH-003',activity:['NEXTDAY','SAMEDAY'],status:'active',phone:'',email:'',createdAt:'2026-11-03T00:00:00.000Z'}];db.paie.elementsVariables=Array.isArray(db.paie.elementsVariables)?db.paie.elementsVariables:[];db.paie.salaries.forEach(x=>{x.activity=Array.isArray(x.activity)?x.activity:(x.activity?[x.activity]:[]);x.status=x.status||'active'});/* PAIE - fin */[...db.rentals,...db.rentalsArchive].forEach(r=>{r.caution=!!r.caution;r.cautionAmount=r.cautionAmount===''||r.cautionAmount==null?null:Number(r.cautionAmount)});db.depots=Array.isArray(db.depots)?db.depots:['DIF4','DPF2','OWV1','A_RENOMMER'];['DIF4','DPF2','OWV1','A_RENOMMER'].forEach(n=>{if(!db.depots.includes(n))db.depots.push(n)});db.vehicles.forEach(v=>{v.depot=typeof v.depot==='string'?v.depot:'';v.transferHistory=Array.isArray(v.transferHistory)?v.transferHistory:[];v.documents=v.documents||{};v.kmHistory=Array.isArray(v.kmHistory)?v.kmHistory:[];v.oilHistory=Array.isArray(v.oilHistory)?v.oilHistory:[];v.kmInitial=v.kmInitial??(v.kmHistory.length?[...v.kmHistory].sort((a,b)=>(a.date||'').localeCompare(b.date||''))[0].km:(v.km??null));v.oilInitial=v.oilInitial??(v.oilHistory.length?[...v.oilHistory].sort((a,b)=>(a.date||'').localeCompare(b.date||''))[0].km:(v.oilLast??(v.oilNext!=null?Math.max(0,Number(v.oilNext)-VIDANGE_INTERVAL):null)));v.pannes=Array.isArray(v.pannes)?v.pannes:[];if(!v.pannes.length&&Array.isArray(v.breakdowns)&&v.breakdowns.length)v.pannes=v.breakdowns.map((b,i)=>({id:`migration-${v.plate}-${i+1}`,date:b.date||'',description:b.description||b.comment||'',photo:b.photo||null,status:v.condition==='HS'?'En cours':'Réparée',dateReparation:'',interventionId:null})).filter(b=>b.description||b.photo);if(!v.pannes.length&&v.condition==='HS'&&String(v.comment||'').trim())v.pannes.push({id:`migration-${v.plate}`,date:'',description:String(v.comment).trim(),photo:null,status:'En cours',dateReparation:'',interventionId:null});v.pannes.forEach(x=>{x.status=x.status||'En cours';x.date=x.date||'';x.dateReparation=x.dateReparation||'';x.description=x.description||''});v.version=v.version??'';v.power=v.power==null?null:Number(v.power);v.prixAchat=v.prixAchat??v.purchasePrice??null;v.prixAchat=v.prixAchat===''||v.prixAchat==null?null:Number(v.prixAchat);v.dateAcquisition=v.dateAcquisition??null;if(v.oilLast==null&&v.oilNext!=null)v.oilLast=Math.max(0,Number(v.oilNext)-VIDANGE_INTERVAL);v.oilLast=v.oilLast==null?null:Number(v.oilLast);v.oilNext=v.oilLast==null?null:v.oilLast+VIDANGE_INTERVAL;v.exitReason=v.exitReason||(v.status==='sorti'?'À préciser':'');v.exitReasonDetail=v.exitReasonDetail||v.exitComment||'';v.exitComment=v.exitComment||'';v.exitDate=v.exitDate||'';});return db}
function load(){try{const saved=JSON.parse(localStorage.getItem(KEY));let source=saved&&Array.isArray(saved.vehicles)?saved:JSON.parse(JSON.stringify(imported));if(source&&Array.isArray(source.rentals))source.rentals=source.rentals.map(r=>({...r,id:r.id||`location-migration-${String(r.plate||'').replace(/[^A-Za-z0-9]/g,'')}`}));migrateDb(source);save();}catch{migrateDb(JSON.parse(JSON.stringify(imported)));try{save()}catch(e){}}}
function openDocDB(){return new Promise((resolve,reject)=>{let r=indexedDB.open('atelier.flotte.documents.v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('docs',{keyPath:'id'});r.onsuccess=()=>{docDB=r.result;resolve(docDB)};r.onerror=()=>reject(r.error)})}
function docId(plate,type){return plate+'::'+type}
function refreshDocIndex(){return new Promise(resolve=>{let r=docDB.transaction('docs').objectStore('docs').getAll();r.onsuccess=()=>{docIndex={};(r.result||[]).forEach(d=>docIndex[d.id]=d);resolve()};r.onerror=()=>resolve()})}
function documentState(v,type){return !!docIndex[docId(v.plate,type)]}
function ctDateFor(v){return docIndex[docId(v.plate,'Contrôle technique')]?.expiryDate||v.ctDate}
function missingCount(v){return DOC_TYPES.filter(t=>!documentState(v,t)).length}
function documentDots(v){return `<span class="doc-dots" title="Documents : CG, assurance, CT, autre">${DOC_TYPES.slice(0,3).map((t,i)=>`<i class="doc-dot ${documentState(v,t)?'present':'missing'}" title="${t} : ${documentState(v,t)?'présent':'manquant'}">${['CG','ASS','CT'][i]}</i>`).join('')}</span>`}
function saveDocument(record){return new Promise((resolve,reject)=>{let r=docDB.transaction('docs','readwrite').objectStore('docs').put(record);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
function deleteDocument(id){return new Promise((resolve,reject)=>{let r=docDB.transaction('docs','readwrite').objectStore('docs').delete(id);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
function getDocument(id){return new Promise((resolve,reject)=>{let r=docDB.transaction('docs').objectStore('docs').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function compressImage(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return resolve(file);let img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{let scale=Math.min(1,1800/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);canvas.toBlob(b=>b?resolve(new File([b],file.name.replace(/\.[^.]+$/,'')+'.jpg',{type:'image/jpeg'})):reject(Error('compression')), 'image/jpeg',.82)};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('image'))};img.src=url})}
