function save(){db.vehicles.forEach(v=>{if(v.oilLast!=null)v.oilNext=Number(v.oilLast)+VIDANGE_INTERVAL});try{localStorage.setItem(KEY,JSON.stringify(db));}catch(e){toast('Enregistrement local impossible. Exportez une sauvegarde et vérifiez l’espace disponible.');throw e}}
function fmtDate(d){if(!d)return '—';const x=new Date(d+'T00:00:00');return isNaN(x)?'—':x.toLocaleDateString('fr-FR')}
function fmtNum(n){return n==null||n===''?'—':Number(n).toLocaleString('fr-FR')}
function currentDate(){return new Date().toISOString().slice(0,10)}
function pill(text,kind=''){return `<span class="pill ${kind}">${esc(text)}</span>`}
function daysTo(d){return d?Math.floor((new Date(d+'T00:00:00')-new Date(currentDate()+'T00:00:00'))/86400000):null}
function stateDate(date){let n=daysTo(date);return n===null?{label:'Non renseigné',kind:'neutral'}:n<0?{label:'Expiré',kind:'bad'}:n<30?{label:`${n} j`,kind:'warn'}:{label:'À jour',kind:'good'}}
function nextOil(v){return v.oilLast!=null?Number(v.oilLast)+VIDANGE_INTERVAL:(v.oilNext==null?null:Number(v.oilNext))}function oilState(v){let next=nextOil(v);if(next==null)return {label:'À renseigner',kind:'neutral'};let gap=next-Number(v.km||0);return gap<=0?{label:'Dépassée',kind:'bad'}:gap<1500?{label:`Dans ${fmtNum(gap)} km`,kind:'warn'}:{label:`Dans ${fmtNum(gap)} km`,kind:'good'}}
function lastKmReadingDate(v){let readings=Array.isArray(v.kmHistory)?v.kmHistory:[],today=currentDate(),valid=d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&d<=today&&!Number.isNaN(Date.parse(d+'T00:00:00')),dates=readings.map(h=>h?.date).filter(valid).sort();return dates.length?dates[dates.length-1]:[v.kmDate,v.dateKm,v.kmCurrentDate,v.currentKmDate].find(valid)||''}
function kmAlert(v){let date=lastKmReadingDate(v);if(!date)return {plate:v.plate,type:'Km non relevé',label:'À relever',kind:'warn',detail:'Aucun relevé km'};let age=Math.floor((new Date(currentDate()+'T00:00:00')-new Date(date+'T00:00:00'))/86400000);return age>15?{plate:v.plate,type:'Km non relevé',label:'À relever',kind:'warn',detail:`Km non relevé depuis ${age} jours`}:null}
function collectAlerts(v){if(v.ownership==='LOCATION'||v.status!=='actif'||v.condition==='HS')return[];let a=[];let add=(type,s,detail)=>{if(s.kind==='bad'||s.kind==='warn')a.push({plate:v.plate,type,label:s.label,kind:s.kind,detail})};add('Contrôle technique',stateDate(ctDateFor(v)),fmtDate(ctDateFor(v)));add('Vidange',oilState(v),`Prochaine à ${fmtNum(nextOil(v))} km`);let km=kmAlert(v);if(km)a.push(km);if(v.cgStatus&&/BLOQU/i.test(v.cgStatus))a.push({plate:v.plate,type:'Carte grise',label:'Bloquée',kind:'bad',detail:v.cgStatus});else if(v.cgStatus&&/FAIRE|ATTENTE|MANQU/i.test(v.cgStatus))a.push({plate:v.plate,type:'Carte grise',label:'À régulariser',kind:'warn',detail:v.cgStatus});else if(!v.cgStatus)a.push({plate:v.plate,type:'Carte grise',label:'À vérifier',kind:'warn',detail:'Situation absente'});return a}
function restoreKmAfterDelete(v,index){v.kmHistory.splice(index,1);let previous=[...v.kmHistory].sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0];v.km=previous?Number(previous.km):(v.kmInitial??null)}
