function init(){const sess=sessionStorage.getItem(SESSION);if(sess){role=sess;showApp()}else $('#login').classList.remove('hidden');$('#today').textContent=new Date().toLocaleDateString('fr-FR',{weekday:'short',day:'2-digit',month:'short',year:'numeric'});$('#login-go').onclick=login;$('#login-pass').onkeydown=e=>{if(e.key==='Enter')login()};$('#logout').onclick=()=>{sessionStorage.removeItem(SESSION);$('#app').classList.add('hidden');$('#login').classList.remove('hidden')};$('#user-chip').onclick=()=>toast(`Profil : ${roleName()}`);$('#export-top').onclick=()=>exportCsv();updatePoleNavigation();document.addEventListener('click',e=>{const p=e.target.closest('[data-pole]'),n=e.target.closest('[data-page]');if(p){e.preventDefault();switchPole(p.dataset.pole)}else if(n){e.preventDefault();nav(n.dataset.page)}});/* PAIE MOBILE - début */const polePicker=$('#mobile-pole-picker'),poleTrigger=$('#mobile-pole-trigger'),poleMenu=$('#mobile-pole-menu');if(polePicker&&poleTrigger&&poleMenu){const closePoleMenu=()=>{poleMenu.hidden=true;poleTrigger.setAttribute('aria-expanded','false')};poleTrigger.onclick=e=>{e.stopPropagation();poleMenu.hidden=!poleMenu.hidden;poleTrigger.setAttribute('aria-expanded',String(!poleMenu.hidden))};document.addEventListener('click',e=>{if(!polePicker.contains(e.target))closePoleMenu();else if(e.target.closest('#mobile-pole-menu [data-pole]'))closePoleMenu()});poleTrigger.addEventListener('keydown',e=>{if(e.key==='Escape'){closePoleMenu();poleTrigger.focus()}});poleMenu.addEventListener('keydown',e=>{if(e.key==='Escape'){closePoleMenu();poleTrigger.focus()}})}/* PAIE MOBILE - fin */}
