/* UTILISATEURS - début */function showApp(){$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#who').textContent=roleName();$('#top-role').textContent=roleName();$('.role-box .avatar').textContent=roleName()[0];$('.user-chip .avatar').textContent=roleName()[0];document.querySelectorAll('[data-admin-only]').forEach(el=>{el.hidden=!isAdministrator()});if(page==='users'&&!isAdministrator())page='dashboard';if(paiePage()&&!canAccessPaie()){page='dashboard';pole='flotte'}updatePoleNavigation();render()}/* UTILISATEURS - fin */
