const PAIE_TYPES=[['prime','Prime','gain'],['heures-sup','Heures supplémentaires','gain'],['panier','Panier','gain'],['indemnite','Indemnité','gain'],['amende','Amende','retenue'],['franchise','Franchise sinistre','retenue'],['avance','Avance à rembourser','retenue']];
function paieMoney(v){return Number(v||0).toLocaleString('fr-FR',{style:'currency',currency:'EUR'})}
function paieType(t){return PAIE_TYPES.find(x=>x[0]===t)||[t||'Autre',t||'Autre','gain']}
