function paieMonthEntries(){return paieEntries().filter(x=>x.month===paieMonth)}
function paieOverview(){const staff=paieSalaries(),active=staff.filter(x=>x.status==='active'),entries=paieMonthEntries(),gains=entries.filter(x=>paieType(x.type)[2]==='gain').reduce((a,x)=>a+Number(x.amount||0),0),deductions=entries.filter(x=>paieType(x.type)[2]==='retenue').reduce((a,x)=>a+Number(x.amount||0),0),drafts=entries.filter(x=>x.status==='draft'),withAny=new Set(entries.map(x=>x.salaryId)),without=active.filter(x=>!withAny.has(x.id));return `<div class="page-head"><div><span class="eyebrow kicker">GESTION / PAIE</span><h1>Vue d’ensemble</h1><p>Suivi des éléments variables · ${esc(paieMonthLabel(paieMonth))}</p></div><label class="paie-month-field">Mois<input id="paie-month" type="month" value="${escapeAttr(paieMonth)}"></label></div><section class="stats-grid"><div class="stat-card"><span class="stat-label">Salariés actifs</span><div class="value"><strong>${active.length}</strong><small>salariés</small></div><span class="stat-icon">♙</span></div><div class="stat-card"><span class="stat-label">Total primes & gains</span><div class="value"><strong>${paieMoney(gains)}</strong></div><span class="stat-icon">＋</span></div><div class="stat-card warn"><span class="stat-label">Total retenues</span><div class="value"><strong>${paieMoney(deductions)}</strong></div><span class="stat-icon">−</span></div><div class="stat-card"><span class="stat-label">Net variable</span><div class="value"><strong>${paieMoney(gains-deductions)}</strong></div><span class="stat-icon">€</span></div></section><section class="panel paie-anomalies"><div class="panel-head"><div><h2>Anomalies à traiter</h2><p>Éléments en attente et saisies manquantes pour ce mois</p></div><span class="eyebrow">${drafts.length+without.length} POINTS</span></div><div class="paie-alert-list">${drafts.length?drafts.map(x=>{const staff=paieSalaries().find(y=>y.id===x.salaryId);return `<div class="paie-alert"><span class="paie-alert-mark">!</span><span><b>Élément en brouillon</b><small>${esc(staff?.name||'Salarié supprimé')} · ${esc(paieType(x.type)[1])} · ${paieMoney(x.amount)}</small></span><button class="btn light small" data-edit-variable="${escapeAttr(x.id)}">Ouvrir</button></div>`}).join(''):'<div class="paie-clear">Aucun élément en brouillon.</div>'}${without.length?without.map(x=>`<div class="paie-alert"><span class="paie-alert-mark missing">·</span><span><b>Aucun élément saisi</b><small>${esc(x.name)} · ${esc(paieMonthLabel(paieMonth))}</small></span><button class="btn light small" data-add-for="${escapeAttr(x.id)}">Saisir</button></div>`).join(''):'<div class="paie-clear">Tous les salariés actifs ont au moins un élément saisi.</div>'}</div></section><div class="paie-overview-foot"><span>${entries.length} élément${entries.length===1?'':'s'} saisi${entries.length===1?'':'s'} ce mois-ci</span><button class="btn primary" data-page="paie-variables">＋ Saisir un élément</button></div>`}
function paieEmployeesPage(){const list=paieSalaries(),rows=list.map(x=>`<tr><td><b>${esc(x.name)}</b><small class="paie-subline">${esc(x.matricule||'Sans matricule')}</small></td><td>${(x.activity||[]).length?x.activity.map(a=>`<span class="user-depot-tag">${esc(a)}</span>`).join(' '):'<span class="muted">Non précisée</span>'}</td><td>${pill(x.status==='active'?'Actif':'Désactivé',x.status==='active'?'good':'neutral')}</td><td>${paieEntries().filter(e=>e.salaryId===x.id).length} élément(s)</td><td class="paie-actions"><button class="btn light small" data-open-salary="${escapeAttr(x.id)}">Fiche</button><button class="btn light small" data-edit-salary="${escapeAttr(x.id)}">Modifier</button><button class="btn light small" data-toggle-salary="${escapeAttr(x.id)}">${x.status==='active'?'Désactiver':'Réactiver'}</button></td></tr>`).join('');return `<div class="page-head"><div><span class="eyebrow kicker">GESTION / PAIE</span><h1>Salariés</h1><p>${list.filter(x=>x.status==='active').length} actifs sur ${list.length} · chauffeurs travaillant sur plusieurs dépôts.</p></div><div class="head-actions"><button class="btn primary" id="add-salary">＋ Ajouter un salarié</button></div></div><div class="table-wrap"><table class="fleet-table paie-table"><thead><tr><th>SALARIÉ / MATRICULE</th><th>ACTIVITÉ</th><th>STATUT</th><th>HISTORIQUE</th><th>ACTIONS</th></tr></thead><tbody>${rows||'<tr><td colspan="5" class="empty-state">Aucun salarié. Ajoutez votre premier salarié.</td></tr>'}</tbody></table></div><div class="table-footer">Aucun rattachement à un dépôt : les salariés peuvent intervenir sur plusieurs sites.</div>`}
function paieEmployeePage(){const x=paieSalaries().find(y=>y.id===selectedSalarie);if(!x)return '<div class="empty-state">Salarié introuvable.</div>';const history=paieEntries().filter(e=>e.salaryId===x.id).sort((a,b)=>(b.month||'').localeCompare(a.month||''));return `<div class="page-head"><div><span class="eyebrow kicker">PAIE / FICHE SALARIÉ</span><h1>${esc(x.name)}</h1><p>${esc(x.matricule||'Sans matricule')} · ${(x.activity||[]).map(esc).join(' / ')||'Activité non précisée'} · ${x.status==='active'?'Actif':'Désactivé'}</p></div><div class="head-actions"><button class="btn light" data-page="paie-employees">← Salariés</button><button class="btn primary" data-add-for="${escapeAttr(x.id)}">＋ Élément variable</button></div></div><section class="panel"><div class="panel-head"><div><h2>Historique des éléments variables</h2><p>${history.length} élément${history.length===1?'':'s'} enregistré${history.length===1?'':'s'}</p></div></div><div class="table-wrap"><table class="fleet-table paie-table"><thead><tr><th>MOIS</th><th>TYPE</th><th>MONTANT</th><th>STATUT</th><th>COMMENTAIRE</th><th>ACTIONS</th></tr></thead><tbody>${history.map(e=>paieVariableRow(e)).join('')||'<tr><td colspan="6" class="empty-state">Aucun élément enregistré.</td></tr>'}</tbody></table></div></section>`}
function paieVariableRow(e){const t=paieType(e.type),sign=t[2]==='retenue'?'−':'＋';return `<tr><td>${esc(paieMonthLabel(e.month||'2026-01'))}</td><td>${esc(t[1])}</td><td class="paie-amount ${t[2]}">${sign} ${paieMoney(e.amount)}</td><td>${pill(e.status==='validated'?'Validé':'Brouillon',e.status==='validated'?'good':'warn')}</td><td>${esc(e.comment||'—')}</td><td class="paie-actions"><button class="btn light small" data-edit-variable="${escapeAttr(e.id)}">Modifier</button>${e.status!=='validated'?`<button class="btn light small" data-validate-variable="${escapeAttr(e.id)}">Valider</button>`:''}<button class="btn danger small" data-delete-variable="${escapeAttr(e.id)}">Supprimer</button></td></tr>`}
function paieVariablesPage(){const rows=paieMonthEntries().sort((a,b)=>(a.createdAt||'').localeCompare(b.createdAt||'')).map(e=>{const st=paieSalaries().find(x=>x.id===e.salaryId);return `<tr><td><b>${esc(st?.name||'Salarié supprimé')}</b></td><td>${esc(paieType(e.type)[1])}</td><td class="paie-amount ${paieType(e.type)[2]}">${paieType(e.type)[2]==='retenue'?'−':'＋'} ${paieMoney(e.amount)}</td><td>${pill(e.status==='validated'?'Validé':'Brouillon',e.status==='validated'?'good':'warn')}</td><td>${esc(e.comment||'—')}</td><td class="paie-actions"><button class="btn light small" data-edit-variable="${escapeAttr(e.id)}">Modifier</button>${e.status!=='validated'?`<button class="btn light small" data-validate-variable="${escapeAttr(e.id)}">Valider</button>`:''}<button class="btn danger small" data-delete-variable="${escapeAttr(e.id)}">Supprimer</button></td></tr>`}).join('');return `<div class="page-head"><div><span class="eyebrow kicker">GESTION / PAIE</span><h1>Éléments variables</h1><p>Saisies par salarié et par mois · gains et retenues.</p></div><div class="head-actions"><label class="paie-month-field">Mois<input id="paie-month" type="month" value="${escapeAttr(paieMonth)}"></label><button class="btn primary" id="add-variable">＋ Saisir un élément</button></div></div><div class="table-wrap"><table class="fleet-table paie-table"><thead><tr><th>SALARIÉ</th><th>TYPE</th><th>MONTANT</th><th>STATUT</th><th>COMMENTAIRE</th><th>ACTIONS</th></tr></thead><tbody>${rows||'<tr><td colspan="6" class="empty-state">Aucun élément pour ce mois. Ajoutez une prime, une indemnité ou une retenue.</td></tr>'}</tbody></table></div><div class="table-footer">${paieMonthEntries().length} élément(s) · gains ${paieMoney(paieMonthEntries().filter(e=>paieType(e.type)[2]==='gain').reduce((a,e)=>a+Number(e.amount||0),0))} · retenues ${paieMoney(paieMonthEntries().filter(e=>paieType(e.type)[2]==='retenue').reduce((a,e)=>a+Number(e.amount||0),0))}</div>`}
function paieSalaryModal(sal){if(!canAccessPaie())return toast('Accès réservé aux rôles Administrateur, Responsable et RH.');const chosen=new Set(sal?.activity||[]),activities=['NEXTDAY','SAMEDAY'];const body=`<form id="paie-salary-form" class="form-grid"><label>Nom complet<input name="name" maxlength="100" required value="${escapeAttr(sal?.name||'')}" placeholder="Ex. Alex Martin"></label><label>Matricule<input name="matricule" maxlength="30" value="${escapeAttr(sal?.matricule||'')}" placeholder="Ex. CH-004"></label><label>Téléphone<input name="phone" type="tel" value="${escapeAttr(sal?.phone||'')}"></label><label>Email<input name="email" type="email" value="${escapeAttr(sal?.email||'')}"></label><fieldset class="paie-activity-field"><legend>Activité (facultatif)</legend>${activities.map(a=>`<label><input type="checkbox" name="activity" value="${a}" ${chosen.has(a)?'checked':''}> ${a}</label>`).join('')}</fieldset></form><p class="form-note">Les salariés ne sont pas rattachés à un dépôt et peuvent travailler sur plusieurs dépôts.</p>`;openModal(sal?'Modifier un salarié':'Ajouter un salarié',body,`<button class="btn light" data-close>Annuler</button><button class="btn primary" id="save-paie-salary">Enregistrer</button>`,'Données conservées localement dans ce navigateur');$('#save-paie-salary').onclick=()=>{if(!canAccessPaie())return toast('Accès refusé.');const f=$('#paie-salary-form');if(!f.reportValidity())return;const value={name:f.elements.name.value.trim(),matricule:f.elements.matricule.value.trim(),phone:f.elements.phone.value.trim(),email:f.elements.email.value.trim(),activity:[...f.querySelectorAll('[name="activity"]:checked')].map(i=>i.value)};if(!value.name)return;if(sal){Object.assign(sal,value);sal.updatedAt=new Date().toISOString()}else paieSalaries().push({id:`sal-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,...value,status:'active',createdAt:new Date().toISOString()});save();closeModal();render();toast(sal?'Salarié modifié.':'Salarié ajouté.')};}
function paieVariableModal(entry,forSalary){if(!canAccessPaie())return toast('Accès réservé aux rôles Administrateur, Responsable et RH.');const staff=paieSalaries().filter(x=>x.status==='active'||x.id===entry?.salaryId),selectedId=forSalary||entry?.salaryId||'',typelist=PAIE_TYPES.map(t=>`<option value="${t[0]}" ${entry?.type===t[0]?'selected':''}>${t[1]} · ${t[2]==='gain'?'gain':'retenue'}</option>`).join('');const body=`<form id="paie-variable-form" class="form-grid"><label>Salarié<select name="salaryId" required><option value="">Choisir…</option>${staff.map(x=>`<option value="${escapeAttr(x.id)}" ${selectedId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Mois<input name="month" type="month" required value="${escapeAttr(entry?.month||paieMonth)}"></label><label>Type<select name="type" required>${typelist}</select></label><label>Montant (€)<input name="amount" type="number" min="0.01" step="0.01" required value="${escapeAttr(entry?.amount??'')}" placeholder="0,00"></label><label class="paie-wide">Commentaire<textarea name="comment" rows="3" maxlength="500" placeholder="Précision utile (facultatif)">${esc(entry?.comment||'')}</textarea></label><label>Statut<select name="status"><option value="draft" ${entry?.status!=='validated'?'selected':''}>Brouillon</option><option value="validated" ${entry?.status==='validated'?'selected':''}>Validé</option></select></label></form><p class="form-note">Prime, heures sup, panier et indemnité sont des gains; amende, franchise sinistre et avance à rembourser sont des retenues.</p>`;openModal(entry?'Modifier un élément variable':'Nouvel élément variable',body,`<button class="btn light" data-close>Annuler</button><button class="btn primary" id="save-paie-variable">Enregistrer</button>`,'Saisie mensuelle · statut brouillon ou validé');$('#save-paie-variable').onclick=()=>{if(!canAccessPaie())return toast('Accès refusé.');const f=$('#paie-variable-form');if(!f.reportValidity())return;const amount=Number(f.elements.amount.value);if(!Number.isFinite(amount)||amount<=0)return toast('Saisissez un montant positif.');const value={salaryId:f.elements.salaryId.value,month:f.elements.month.value,type:f.elements.type.value,amount,comment:f.elements.comment.value.trim(),status:f.elements.status.value};if(entry){Object.assign(entry,value);entry.updatedAt=new Date().toISOString()}else paieEntries().push({id:`ev-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,...value,createdAt:new Date().toISOString()});paieMonth=value.month;save();closeModal();render();toast(entry?'Élément modifié.':'Élément enregistré.')};}
function bindPaieActions(){const month=$('#paie-month');if(month)month.onchange=()=>{if(/^\d{4}-\d{2}$/.test(month.value)){paieMonth=month.value;render()}};const addSalary=$('#add-salary');if(addSalary)addSalary.onclick=()=>paieSalaryModal();document.querySelectorAll('[data-edit-salary]').forEach(b=>b.onclick=()=>{const x=paieSalaries().find(y=>y.id===b.dataset.editSalary);if(x)paieSalaryModal(x)});document.querySelectorAll('[data-open-salary]').forEach(b=>b.onclick=()=>{selectedSalarie=b.dataset.openSalary;nav('paie-employee')});document.querySelectorAll('[data-toggle-salary]').forEach(b=>b.onclick=()=>{const x=paieSalaries().find(y=>y.id===b.dataset.toggleSalary);if(!x)return;x.status=x.status==='active'?'inactive':'active';x.updatedAt=new Date().toISOString();save();render();toast(x.status==='active'?'Salarié réactivé.':'Salarié désactivé.')});const addVariable=$('#add-variable');if(addVariable)addVariable.onclick=()=>paieVariableModal();document.querySelectorAll('[data-add-for]').forEach(b=>b.onclick=()=>paieVariableModal(null,b.dataset.addFor));document.querySelectorAll('[data-edit-variable]').forEach(b=>b.onclick=()=>{const x=paieEntries().find(y=>y.id===b.dataset.editVariable);if(x)paieVariableModal(x)});document.querySelectorAll('[data-validate-variable]').forEach(b=>b.onclick=()=>{if(!canAccessPaie())return toast('Accès refusé.');const x=paieEntries().find(y=>y.id===b.dataset.validateVariable);if(!x)return;x.status='validated';x.updatedAt=new Date().toISOString();save();render();toast('Élément validé.')});document.querySelectorAll('[data-delete-variable]').forEach(b=>b.onclick=()=>{if(!canAccessPaie())return toast('Accès refusé.');const x=paieEntries().find(y=>y.id===b.dataset.deleteVariable);if(!x||!confirm('Supprimer définitivement cet élément variable ?'))return;db.paie.elementsVariables=db.paie.elementsVariables.filter(y=>y.id!==x.id);save();render();toast('Élément supprimé.')});}
/* PAIE - fin */

/* UTILISATEURS - début */
function usersPage(){
 if(!isAdministrator())return '<div class="empty-state">Accès réservé au rôle Administrateur.</div>';
 const users=db.users||[];
 const rows=users.map(u=>`<tr><td><b>${esc(u.name)}</b><small style="display:block;color:#89948d;margin-top:3px">${esc(u.email)}</small></td><td>${esc(u.role)}</td><td>${(u.depots||[]).length?(u.depots||[]).map(d=>`<span class="user-depot-tag">${esc(d)}</span>`).join(' '):'<span class="muted">Aucun dépôt</span>'}</td><td>${pill(u.status==='active'?'Actif':u.status==='disabled'?'Désactivé':'Invité',u.status==='active'?'good':u.status==='disabled'?'neutral':'warn')}</td><td class="user-row-actions"><button class="btn light small" data-user-preview="${escapeAttr(u.id)}">Aperçu mail</button><button class="btn light small" data-user-edit="${escapeAttr(u.id)}">Modifier</button><button class="btn light small" data-user-toggle="${escapeAttr(u.id)}">${u.status==='active'?'Désactiver':'Activer'}</button><button class="btn danger small" data-user-delete="${escapeAttr(u.id)}">Supprimer</button></td></tr>`).join('');
 return `<div class="page-head"><div><span class="eyebrow kicker">ADMINISTRATION / ACCÈS LOCAUX</span><h1>Utilisateurs</h1><p>${users.length} compte${users.length===1?'':'s'} de démonstration · conservés dans le stockage local de cet appareil.</p></div><div class="head-actions"><button class="btn primary" id="invite-user">＋ Inviter un utilisateur</button></div></div><div class="archive-banner">Les invitations sont simulées : aucun courriel n’est envoyé. Un aperçu est disponible avant l’enregistrement.</div><div class="table-wrap"><table class="fleet-table users-table"><thead><tr><th>NOM / EMAIL</th><th>RÔLE</th><th>DÉPÔTS AFFECTÉS</th><th>STATUT</th><th>ACTIONS</th></tr></thead><tbody>${rows||'<tr><td colspan="5" class="empty-state">Aucun utilisateur enregistré. Invitez un utilisateur pour commencer.</td></tr>'}</tbody></table></div><div class="table-footer">L’écran Utilisateurs et ses actions sont réservés au profil Administrateur. Les profils existants ne possèdent pas de dépôt utilisateur attribué dans le code.</div>`;
}
function userFormModal(user){
 if(!isAdministrator())return toast('Accès réservé au rôle Administrateur.');
 const edit=!!user,assigned=new Set(user?.depots||[]),depotNames=Array.isArray(db.depots)?db.depots:[];
 const roles=[['responsable','Responsable'],['rh','RH'],['chef','Chef d’équipe'],['administrateur','Administrateur']];
 const form=`<form id="user-form" class="form-grid"><label>Nom complet<input name="name" maxlength="100" required value="${escapeAttr(user?.name||'')}" placeholder="Ex. Alex Martin"></label><label>Adresse email<input name="email" type="email" maxlength="254" required value="${escapeAttr(user?.email||'')}" placeholder="nom@exemple.fr"></label><label>Rôle<select name="role" required>${roles.map(([value,label])=>`<option value="${value}" ${user?.role===value?'selected':''}>${label}</option>`).join('')}</select></label><fieldset class="user-depots-field"><legend>Dépôts affectés</legend><div class="user-depot-options">${depotNames.length?depotNames.map(d=>`<label class="user-depot-choice"><input type="checkbox" name="depots" value="${escapeAttr(d)}" ${assigned.has(d)?'checked':''}><span>${esc(d)}</span></label>`).join(''):'<small>Aucun dépôt défini dans les données.</small>'}</div></fieldset></form><p class="form-note">${edit?'Les changements sont enregistrés uniquement dans ce navigateur.':'Après enregistrement, le compte apparaît avec le statut « Invité ». Aucun email n’est envoyé.'}</p>`;
 openModal(edit?'Modifier un utilisateur':'Inviter un utilisateur',form,`<button class="btn light" data-close>Annuler</button><button class="btn light" id="preview-user-mail">Aperçu du mail</button><button class="btn primary" id="save-user">${edit?'Enregistrer':'Créer l’invitation'}</button>`,'Démonstration locale · pas d’envoi de courriel');
 const readForm=()=>{const f=$('#user-form');return{name:f.elements.name.value.trim(),email:f.elements.email.value.trim(),role:f.elements.role.value,depots:[...f.querySelectorAll('input[name="depots"]:checked')].map(x=>x.value)}};
 $('#preview-user-mail').onclick=()=>{const value=readForm();if(!value.name||!value.email||!$('#user-form').reportValidity())return;userMailPreview(value)};
 $('#save-user').onclick=()=>{if(!isAdministrator())return toast('Accès réservé au rôle Administrateur.');const value=readForm();if(!$('#user-form').reportValidity())return;const duplicate=db.users.some(x=>x.email.toLowerCase()===value.email.toLowerCase()&&x.id!==user?.id);if(duplicate)return toast('Cette adresse email est déjà enregistrée.');if(edit){Object.assign(user,value);user.updatedAt=new Date().toISOString()}else db.users.push({id:`user-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,...value,status:'invited',createdAt:new Date().toISOString()});save();closeModal();render();toast(edit?'Utilisateur mis à jour.':'Invitation créée (non envoyée).')};
}
function userMailPreview(user){
 if(!isAdministrator())return toast('Accès réservé au rôle Administrateur.');
 const depots=(user.depots||[]).length?user.depots.join(', '):'Aucun dépôt affecté';
 const body=`<div class="invitation-mail"><p class="eyebrow">APERÇU · EMAIL DE DÉMONSTRATION</p><div class="invitation-mail-meta"><b>À</b><span>${esc(user.email)}</span><b>Objet</b><span>Invitation à rejoindre GestPilot — Gestion transport</span></div><hr><p>Bonjour ${esc(user.name)},</p><p>Vous êtes invité(e) à rejoindre l’espace de gestion flotte GestPilot.</p><p><b>Rôle :</b> ${esc(({responsable:'Responsable',rh:'RH',chef:'Chef d’équipe',administrateur:'Administrateur'})[user.role]||user.role)}<br><b>Dépôts affectés :</b> ${esc(depots)}</p><p>Cette invitation est un aperçu de démonstration. Aucun message n’a été envoyé et aucun accès réel n’est créé.</p><p>À bientôt,<br>L’équipe GestPilot</p></div>`;
 openModal('Aperçu du mail d’invitation',body,'<button class="btn primary" data-close>Fermer</button>','Simulation locale · aucun email envoyé');
}
function bindUserActions(){
 if(!isAdministrator())return;
 const invite=$('#invite-user');if(invite)invite.onclick=()=>userFormModal(null);
 document.querySelectorAll('[data-user-preview]').forEach(b=>b.onclick=()=>{const u=db.users.find(x=>x.id===b.dataset.userPreview);if(u)userMailPreview(u)});
 document.querySelectorAll('[data-user-edit]').forEach(b=>b.onclick=()=>{const u=db.users.find(x=>x.id===b.dataset.userEdit);if(u)userFormModal(u)});
 document.querySelectorAll('[data-user-toggle]').forEach(b=>b.onclick=()=>{const u=db.users.find(x=>x.id===b.dataset.userToggle);if(!u)return;u.status=u.status==='active'?'disabled':'active';u.updatedAt=new Date().toISOString();save();render();toast(u.status==='active'?'Utilisateur activé.':'Utilisateur désactivé.')});
 document.querySelectorAll('[data-user-delete]').forEach(b=>b.onclick=()=>{const u=db.users.find(x=>x.id===b.dataset.userDelete);if(!u||!confirm(`Supprimer l’utilisateur ${u.name} (${u.email}) ?`))return;db.users=db.users.filter(x=>x.id!==u.id);save();render();toast('Utilisateur supprimé.')});
}
/* UTILISATEURS - fin */
function dashboard(){let vs=activeVehicles(),rentalFleet=db.rentals||[],rentalState=r=>{let s=String(r.condition||'').trim().toUpperCase();if(!['ROULANT','HS'].includes(s))s=String(r.status||'').trim().toUpperCase();return s==='HS'?'HS':'ROULANT'},rentalRun=rentalFleet.filter(r=>rentalState(r)==='ROULANT').length,rentalHs=rentalFleet.length-rentalRun,activeTotal=vs.length+rentalFleet.length,purchasedRun=vs.filter(v=>v.condition==='ROULANT').length,run=purchasedRun+rentalRun,hs=vs.length-purchasedRun+rentalHs,alerts=allAlerts(),red=alerts.filter(a=>a.kind==='bad').length;const activities=[...new Set(vs.map(v=>v.activity).filter(Boolean))],companies=[...new Set(vs.map(v=>v.company).filter(Boolean))];let split=(list,key)=>list.map(n=>{let g=vs.filter(v=>v[key]===n),r=g.filter(v=>v.condition==='ROULANT').length,h=g.length-r;return `<div class="split-row"><b class="split-name">${esc(n)}</b><div class="split-track"><span class="run" style="width:${g.length?r/g.length*100:0}%"></span><span class="hs" style="width:${g.length?h/g.length*100:0}%"></span></div><span class="split-num">${r} / ${h}</span></div>`}).join('');let lessors=[...new Set(rentalFleet.map(r=>String(r.lessor||'').trim()||'Loueur non renseigné'))],rentalSplit=lessors.map(n=>{let g=rentalFleet.filter(r=>(String(r.lessor||'').trim()||'Loueur non renseigné')===n),r=g.filter(v=>rentalState(v)==='ROULANT').length,h=g.length-r;return `<div class="split-row"><b class="split-name">${esc(n)}</b><div class="split-track"><span class="run" style="width:${g.length?r/g.length*100:0}%"></span><span class="hs" style="width:${g.length?h/g.length*100:0}%"></span></div><span class="split-num">${r} / ${h}</span></div>`}).join('');let ordered=[...alerts].sort((a,b)=>(a.kind==='bad'?-1:1)-(b.kind==='bad'?-1:1)),top=ordered.slice(0,5);if(ordered.some(a=>a.type==='Km non relevé')&&!top.some(a=>a.type==='Km non relevé'))top=[...top.slice(0,4),ordered.find(a=>a.type==='Km non relevé')].sort((a,b)=>(a.kind==='bad'?-1:1)-(b.kind==='bad'?-1:1));return `<div class="page-head"><div><span class="eyebrow kicker">LUNDI · 02 NOVEMBRE 2026</span><h1>Vue d’ensemble</h1><p>Votre parc, ses disponibilités et ses échéances prioritaires.</p></div></div><section class="stats-grid"><div class="stat-card"><span class="stat-label">Parc actif</span><div class="value"><strong>${activeTotal}</strong><small>véhicules</small></div><span class="stat-icon">▤</span></div><div class="stat-card"><span class="stat-label">Disponibles</span><div class="value"><strong>${run}</strong><small>roulants</small></div><span class="stat-icon">✓</span></div><div class="stat-card warn"><span class="stat-label">Hors service</span><div class="value"><strong>${hs}</strong><small>à traiter</small></div><span class="stat-icon">⚒</span></div><div class="stat-card warn"><span class="stat-label">Alertes à suivre</span><div class="value"><strong>${alerts.length}</strong><small>${red} prioritaires</small></div><span class="stat-icon">!</span></div></section><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>Répartition du parc</h2><p>Véhicules roulants / hors service</p></div><span class="eyebrow">${activeTotal} ACTIFS</span></div><div class="fleet-split">${split(activities,'activity')}<div style="height:1px;background:#edf0eb;margin:17px 0"></div>${split(companies,'company')}<div style="height:1px;background:#edf0eb;margin:17px 0"></div><div class="eyebrow" style="display:flex;justify-content:space-between;margin:0 0 10px"><span>LOCATIONS</span><span>${rentalFleet.length} VÉHICULE${rentalFleet.length===1?'':'S'}</span></div>${rentalSplit||'<div class="split-row"><b class="split-name">—</b><div></div><span class="split-num">0 / 0</span></div>'}<div class="split-legend"><span><i class="legend-dot" style="background:#6e9b7f"></i>Roulant</span><span><i class="legend-dot" style="background:#d58b6c"></i>HS</span></div></div></section><section class="panel alerts-panel"><div class="panel-head"><div><h2>À surveiller</h2><p>Échéances, incidents et relevés kilométriques à effectuer</p></div><button class="link-button" data-jump="alerts">Tout voir →</button></div><div class="alert-list">${top.length?top.map(a=>`<div class="alert-row" data-plate="${escapeAttr(a.plate)}"><span class="alert-symbol ${a.kind==='bad'?'red':''}">${a.kind==='bad'?'!':'◷'}</span><div class="alert-copy"><b>${esc(a.plate)} · ${esc(a.type)}</b><small>${esc(a.detail)}</small></div><span class="alert-date">${esc(a.label)}</span></div>`).join(''):'<div class="empty-state">Aucune alerte en cours.</div>'}</div></section></div><div class="attention-band"><span class="band-icon">✦</span><div><strong>${red} échéances / statuts urgents identifiés</strong><small>Vérifiez les CT expirés et les véhicules hors service.</small></div><button data-jump="alerts">Consulter les alertes →</button></div>`}
function vehiclesPage(){let vs=activeVehicles().filter(v=>(!filters.search||[v.plate,v.brand,v.model,v.company].some(x=>String(x||'').toLowerCase().includes(filters.search.toLowerCase())))&&(!filters.activity||v.activity===filters.activity)&&(!filters.company||v.company===filters.company)&&(!filters.condition||v.condition===filters.condition)&&(!filters.missingDocs||missingCount(v)>0)&&(!filters.depot||(filters.depot==='__unassigned__'?!v.depot:v.depot===filters.depot)));let acts=[...new Set(activeVehicles().map(v=>v.activity).filter(Boolean))],cos=[...new Set(activeVehicles().map(v=>v.company).filter(Boolean))];return `<div class="page-head"><div><span class="eyebrow kicker">PARC AUTOMOBILE / ACTIFS</span><h1>Véhicules</h1><p>${vs.length} véhicule${vs.length===1?'':'s'} affiché${vs.length===1?'':'s'} sur ${activeVehicles().length} actifs</p></div><div class="head-actions">${canEdit()?'<button class="btn primary" id="add-vehicle">＋ Ajouter</button>':''}<button class="btn light" id="export-list">⇩ CSV</button></div></div><div class="filterbar"><div class="searchbox"><span>⌕</span><input id="search" placeholder="Rechercher une plaque, marque…" value="${esc(filters.search)}"></div><select id="filter-activity"><option value="">Toutes les activités</option>${acts.map(a=>`<option ${filters.activity===a?'selected':''}>${esc(a)}</option>`).join('')}</select><select id="filter-company"><option value="">Toutes les sociétés</option>${cos.map(a=>`<option ${filters.company===a?'selected':''}>${esc(a)}</option>`).join('')}</select><select id="filter-depot"><option value="">Tous les dépôts</option><option value="__unassigned__" ${filters.depot==='__unassigned__'?'selected':''}>À affecter</option>${db.depots.map(d=>`<option value="${escapeAttr(d)}" ${filters.depot===d?'selected':''}>${esc(d)}</option>`).join('')}</select><select id="filter-condition"><option value="">Tous les états</option><option ${filters.condition==='ROULANT'?'selected':''}>ROULANT</option><option ${filters.condition==='HS'?'selected':''}>HS</option></select><label class="check-filter"><input type="checkbox" id="filter-missing-docs" ${filters.missingDocs?'checked':''}> Documents manquants</label></div><div class="table-wrap"><table class="fleet-table"><thead><tr><th>IMMATRICULATION</th><th>VÉHICULE</th><th>ACTIVITÉ / SOCIÉTÉ</th><th>DÉPÔT</th><th>ÉTAT</th><th>KM ACTUEL</th><th>PROCHAINE VIDANGE</th><th>CONTRÔLE TECHNIQUE</th><th>DOCS</th><th>ACCÈS</th></tr></thead><tbody>${vs.length?vs.map(v=>{let c=stateDate(ctDateFor(v)),o=oilState(v);return `<tr data-plate="${escapeAttr(v.plate)}"><td class="plate">${esc(v.plate)}</td><td class="vehicle-model"><b>${esc(v.brand||'—')} ${esc(v.model||'')}</b><small>${v.year||'Année n/r'}</small></td><td>${esc(v.activity||'—')}<small style="display:block;color:#89948d;margin-top:3px">${esc(v.company||'—')}</small></td><td>${esc(v.depot||'À affecter')}</td><td>${pill(v.condition,v.condition==='HS'?'bad':'')}</td><td>${fmtNum(v.km)} km</td><td>${pill(o.label,o.kind==='good'?'':o.kind)}</td><td>${c.kind==='good'?pill(fmtDate(ctDateFor(v))):pill(c.label+' · '+fmtDate(ctDateFor(v)),c.kind)}</td><td>${documentDots(v)}</td><td><button class="btn light small quick-docs" data-doc-plate="${escapeAttr(v.plate)}">▤ Docs</button></td></tr>`}).join(''):'<tr><td colspan="10" class="empty-state">Aucun véhicule ne correspond à ces filtres.</td></tr>'}</tbody></table></div><div class="table-footer">Source importée · ${activeVehicles().length} actifs · Cliquer une ligne pour ouvrir la fiche</div>`}
function depotCounts(name){let vs=activeVehicles().filter(v=>name==='__unassigned__'?!v.depot:v.depot===name),alerts=allAlerts();return{vs,run:vs.filter(v=>v.condition!=='HS').length,hs:vs.filter(v=>v.condition==='HS').length,al:alerts.filter(a=>vs.some(v=>v.plate===a.plate)).length}}
function depotsPage(){let unassigned=db.vehicles.filter(v=>v.status==='actif'&&v.ownership!=='LOCATION'&&!v.depot).length;return `<div class="page-head"><div><span class="eyebrow kicker">PARC AUTOMOBILE / SITES</span><h1>Dépôts</h1><p>${db.depots.length} dépôts · les véhicules non affectés restent dans « À affecter »</p></div><div class="head-actions"><button class="btn primary" id="add-depot">＋ Ajouter un dépôt</button></div></div><button class="detail-section depot-card depot-unassigned" type="button" data-open-depot="__unassigned__"><span class="depot-unassigned-copy"><b>À affecter</b><small>Véhicules actifs sans dépôt</small></span><span class="depot-unassigned-count">${unassigned}</span><span class="depot-open-hint">Voir la liste →</span></button><div class="depot-grid">${db.depots.map(name=>{let count=depotCounts(name),rentals=db.rentals.filter(r=>r.depot===name).sort((a,b)=>String(a.plate||'').localeCompare(String(b.plate||''),'fr',{numeric:true,sensitivity:'base'})),total=db.vehicles.filter(v=>v.depot===name&&v.ownership!=='LOCATION').length+rentals.length,vehicles=[...count.vs].sort((a,b)=>String(a.plate||'').localeCompare(String(b.plate||''),'fr',{sensitivity:'base',numeric:true})),alertPlates=new Set(allAlerts().map(a=>a.plate));let activity=name==='DPF2'?['NEXTDAY','SAMEDAY'].map(a=>`<span>${a}<b>${count.vs.filter(v=>v.activity===a).length}</b></span>`).join(''):'';let vehicleList=vehicles.map(v=>`<div class="depot-mini-row" data-open-vehicle="${escapeAttr(v.plate)}" tabindex="0" role="button" aria-label="Ouvrir la fiche de ${escapeAttr(v.plate)}"><b class="depot-mini-plate">${esc(v.plate||'—')}</b><span class="depot-mini-model">${esc([v.brand,v.model].filter(Boolean).join(' ')||'—')}</span>${name==='DPF2'&&['NEXTDAY','SAMEDAY'].includes(v.activity)?`<small class="depot-mini-activity">${esc(v.activity)}</small>`:''}<span class="depot-mini-state ${v.condition==='HS'?'is-hs':'is-running'}">${v.condition==='HS'?'HS':'ROULANT'}</span>${alertPlates.has(v.plate)?'<i class="depot-mini-alert" title="Alerte" aria-label="Alerte"></i>':''}</div>`).join(''),rentalList=rentals.map(r=>`<div class="depot-mini-row"><b class="depot-mini-plate">${esc(r.plate||'—')}</b><span class="depot-mini-model">${esc([r.brand,r.model].filter(Boolean).join(' ')||'—')}</span><small class="depot-mini-activity">LOCATION</small></div>`).join(''),allRows=vehicleList+rentalList,empty=allRows||'<div class="depot-mini-empty">Aucun véhicule ni location</div>';let activityHtml=name==='DPF2'?`<div class="depot-activities"><small>ACTIVITÉ · DPF2</small>${activity}</div>`:'';return `<article class="detail-section depot-card depot-card-clickable" role="button" tabindex="0" data-open-depot="${escapeAttr(name)}" aria-label="Ouvrir le dépôt ${escapeAttr(name)}"><div class="depot-card-head"><h2>${esc(name)}</h2><span class="depot-total">${total} véhicule${total===1?'':'s'} · locations incluses</span></div><div class="depot-metrics"><span>En service <b>${count.run}</b></span><span>HS <b>${count.hs}</b></span><span>Alertes <b>${count.al}</b></span></div>${activityHtml}<section class="depot-mini-section" aria-label="Véhicules et locations affectés"><div class="depot-mini-head"><b>Véhicules & locations</b><span>${vehicles.length+rentals.length}</span></div><div class="depot-mini-list">${empty}</div></section><div class="depot-actions"><button class="btn light small" data-rename-depot="${escapeAttr(name)}">Renommer</button><button class="btn danger small" data-remove-depot="${escapeAttr(name)}">Retirer</button></div></article>`}).join('')}</div><div class="table-footer">Les totaux incluent véhicules achetés et locations; en service, HS et alertes concernent les véhicules achetés actifs.</div>`}
function depotDetailPage(){
 let name=selectedDepot||'__unassigned__';
 let isUnassigned=name==='__unassigned__';
 let title=isUnassigned?'À affecter':name;
 let vehicles=isUnassigned?db.vehicles.filter(v=>v.status==='actif'&&v.ownership!=='LOCATION'&&!v.depot):db.vehicles.filter(v=>v.depot===name&&v.ownership!=='LOCATION');
 let rentals=isUnassigned?[]:db.rentals.filter(r=>r.depot===name).sort((a,b)=>String(a.plate||'').localeCompare(String(b.plate||''),'fr',{numeric:true,sensitivity:'base'}));
 let counts=depotCounts(name),total=vehicles.length+rentals.length,subtitle=isUnassigned?'Véhicules actifs à affecter à un dépôt.':`${total} véhicule${total===1?'':'s'} ou location affecté${total===1?'':'s'} au dépôt`;
 let activity=name==='DPF2'?`<div class="depot-activities depot-detail-activities"><small>ACTIVITÉ · DPF2</small>${['NEXTDAY','SAMEDAY'].map(a=>`<span>${a}<b>${counts.vs.filter(v=>v.activity===a).length}</b></span>`).join('')}</div>`:'';
 let list=vehicles.map(v=>{let state=v.condition,kind=v.condition==='HS'?'bad':'',transfer=`<button class="btn light small" data-transfer-plate="${escapeAttr(v.plate)}">${isUnassigned?'Affecter':'Transférer'}</button>`;return `<article class="depot-vehicle-row" data-open-vehicle="${escapeAttr(v.plate)}" tabindex="0" role="button" aria-label="Ouvrir la fiche de ${escapeAttr(v.plate)}"><div class="depot-vehicle-primary"><b class="plate">${esc(v.plate)}</b><span>${esc([v.brand,v.model].filter(Boolean).join(' ')||'—')}</span></div><div class="depot-vehicle-meta"><span>${esc(v.activity||'—')}</span>${pill(state,kind)}<span>${fmtNum(v.km)} km</span></div>${transfer}</article>`}).join('');
 let rentalRows=rentals.map(r=>`<article class="depot-vehicle-row depot-rental-row" data-open-rental-id="${escapeAttr(r.id)}" tabindex="0" role="button" aria-label="Ouvrir la fiche de location ${escapeAttr(r.plate||'')}"><div class="depot-vehicle-primary"><b class="plate">${esc(r.plate||'—')}</b><span>${esc([r.brand,r.model].filter(Boolean).join(' ')||'—')}</span></div><div class="depot-vehicle-meta"><span>${esc(r.activity||'—')}</span>${pill('LOCATION','blue')}<span>${esc(r.lessor||'—')}</span></div>${canEdit()?`<button class="btn light small" data-transfer-rental="${escapeAttr(r.id)}">Transférer</button>`:''}</article>`).join('');
 let empty=isUnassigned?'Aucun véhicule à affecter.':'Aucun véhicule ni location dans ce dépôt.';
 let addButton=!isUnassigned?`${canEdit()?'<button class="btn primary" id="add-depot-vehicle">＋ Affecter un véhicule acheté</button><button class="btn primary" id="add-depot-rental">＋ Ajouter une location</button>':''}<button class="btn light small" data-rename-depot="${escapeAttr(name)}">Renommer</button><button class="btn danger small" data-remove-depot="${escapeAttr(name)}">Retirer</button>`:'';
 let unassignedNotice=isUnassigned?'<div class="archive-banner">Ces véhicules n’ont pas encore de dépôt. Utilisez « Affecter » sur une ligne pour choisir leur destination.</div>':'';
 let rows=total?`<div class="depot-vehicle-list">${list}${rentalRows}</div>`:`<div class="empty-state">${empty}</div>`;
 return `<div class="page-head depot-detail-head"><div><button class="link-button" id="back-to-depots">← Dépôts</button><span class="eyebrow kicker depot-detail-kicker">FLOTTE / DÉPÔTS</span><h1>${esc(title)}</h1><p>${subtitle}</p></div><div class="head-actions">${addButton}</div></div>${unassignedNotice}<section class="stats-grid depot-detail-stats"><div class="stat-card"><span class="stat-label">Total</span><div class="value"><strong>${total}</strong><small>véhicules & locations</small></div></div><div class="stat-card"><span class="stat-label">En service</span><div class="value"><strong>${counts.run}</strong><small>roulants (achetés)</small></div></div><div class="stat-card warn"><span class="stat-label">HS</span><div class="value"><strong>${counts.hs}</strong><small>à traiter</small></div></div><div class="stat-card warn"><span class="stat-label">Alertes</span><div class="value"><strong>${counts.al}</strong><small>à suivre</small></div></div></section>${activity}<section class="detail-section depot-vehicles-section"><div class="depot-detail-list-head"><h2>Véhicules & locations</h2><span>${total} résultat${total===1?'':'s'}</span></div>${rows}</section>`;
}
function depotModal(name){let edit=name!=null;openModal(edit?'Renommer un dépôt':'Ajouter un dépôt',`<form id="depot-form" class="form-grid"><label class="full">Nom du dépôt<input name="name" required maxlength="40" value="${escapeAttr(name||'')}" placeholder="Ex. DIF4"></label></form>`,`<button class="btn light" data-close>Annuler</button><button class="btn primary" id="save-depot">${edit?'Enregistrer':'Ajouter'}</button>`);$('#save-depot').onclick=()=>{let value=$('#depot-form').elements.name.value.trim();if(!value)return toast('Saisissez un nom de dépôt.');if(db.depots.some(x=>x!==name&&keyText(x)===keyText(value)))return toast('Ce dépôt existe déjà.');if(edit){db.depots[db.depots.indexOf(name)]=value;db.vehicles.forEach(v=>{if(v.depot===name)v.depot=value});}else db.depots.push(value);save();closeModal();render();toast(edit?'Dépôt renommé.':'Dépôt ajouté.')};}
function removeDepot(name){let assigned=[...db.vehicles.filter(v=>v.ownership!=='LOCATION'&&v.depot===name),...db.rentals.filter(r=>r.depot===name)];if(assigned.length)return toast(`Retrait refusé : ${assigned.length} véhicule(s) affecté(s). Réaffectez-les d’abord.`);if(!confirm(`Retirer le dépôt « ${name} » ? Cette action est définitive.`))return;db.depots=db.depots.filter(x=>x!==name);save();render();toast('Dépôt retiré.')}
function alertsPage(){let alerts=allAlerts().sort((a,b)=>a.kind==='bad'?-1:1);let cats=['Contrôle technique','Vidange','Assurance','Carte grise','Panne','Km non relevé'];return `<div class="page-head"><div><span class="eyebrow kicker">SUIVI DU PARC</span><h1>Alertes</h1><p>Statut rouge si échéance CT dépassée · orange si échéance sous 30 jours ou relevé km à effectuer.</p></div><button class="btn light" id="export-alerts">⇩ CSV</button></div><div class="alert-cards">${cats.map((c,i)=>{let n=alerts.filter(a=>a.type===c).length;return `<div class="alert-card"><span class="alert-symbol">${['◷','⚙','⌁','▣','!','↻'][i]}</span><div><strong>${n}</strong><small>${c}</small></div></div>`}).join('')}</div><div class="table-wrap"><table class="fleet-table"><thead><tr><th>PRIORITÉ</th><th>IMMATRICULATION</th><th>ALERTE</th><th>DÉTAIL</th><th>STATUT</th></tr></thead><tbody>${alerts.length?alerts.map(a=>`<tr data-plate="${escapeAttr(a.plate)}"><td>${pill(a.kind==='bad'?'Urgent':'À planifier',a.kind)}</td><td class="plate">${esc(a.plate)}</td><td>${esc(a.type)}</td><td>${esc(a.detail)}</td><td>${pill(a.label,a.kind)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty-state">Aucune alerte calculée.</td></tr>'}</tbody></table></div><div class="table-footer">Les alertes d’échéance restent applicables au contrôle technique et à la vidange. Le statut assurance repose sur la présence de l’attestation.</div>`}
function rentalValues(field){return [...new Set([...db.vehicles.map(v=>v[field]),...db.rentals.map(r=>r[field])].map(x=>String(x||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr',{sensitivity:'base'}))}
function rentalsPage(){let rows=[...db.rentals].sort((a,b)=>String(a.plate).localeCompare(String(b.plate),'fr',{numeric:true,sensitivity:'base'})),archived=[...(db.rentalsArchive||[])].sort((a,b)=>String(b.returnDate||'').localeCompare(String(a.returnDate||''))||String(a.plate||'').localeCompare(String(b.plate||''),'fr',{numeric:true,sensitivity:'base'}));let rowHtml=(r,returned=false)=>`<tr data-rental-id="${escapeAttr(r.id)}" tabindex="0" role="button" aria-label="Ouvrir la fiche de location ${escapeAttr(r.plate||'')}"><td class="plate">${esc(r.plate||'')}</td><td class="vehicle-model"><b>${esc(r.brand||'—')} ${esc(r.model||'')}</b></td><td>${esc(r.activity||'—')}</td><td>${esc(r.depot||'—')}</td><td>${esc(r.lessor||'—')}</td><td>${fmtNum(r.price)} €</td><td>${fmtDate(r.entryDate)}</td><td>${returned?fmtDate(r.returnDate):fmtDate(r.exitDate)}</td><td class="rental-actions">${returned?'<span class="pill neutral">RENDUE</span>':`${canEdit()?`<button class="btn primary small" data-return-rental="${escapeAttr(r.id)}">Rendre</button> <button class="btn light small" data-edit-rental="${escapeAttr(r.id)}">Modifier</button> <button class="btn danger small" data-delete-rental="${escapeAttr(r.id)}">Supprimer</button>`:'—'}`}</td></tr>`;return `<div class="page-head"><div><span class="eyebrow kicker">PARC AUTOMOBILE / CONTRATS</span><h1>Locations</h1><p>${rows.length} location${rows.length===1?'':'s'} active${rows.length===1?'':'s'} · ${archived.length} rendue${archived.length===1?'':'s'}</p></div><div class="head-actions">${canEdit()?'<button class="btn primary" id="add-rental">＋ Ajouter une location</button>':''}</div></div><div class="archive-banner">Les locations actives sont comptées dans la répartition et les dépôts. Les locations rendues sont archivées ici sans compter dans le parc.</div><div class="table-wrap"><table class="fleet-table rental-table"><thead><tr><th>IMMATRICULATION</th><th>VÉHICULE</th><th>ACTIVITÉ</th><th>DÉPÔT</th><th>LOUEUR</th><th>PRIX / LOCATION</th><th>ENTRÉE</th><th>${rows.length?'SORTIE PRÉVUE':'SORTIE PRÉVUE'}</th><th>ACCÈS</th></tr></thead><tbody>${rows.length?rows.map(r=>rowHtml(r)).join(''):'<tr><td colspan="9" class="empty-state">Aucune location active.</td></tr>'}</tbody></table></div><section class="rental-archive-section"><div class="rental-archive-heading"><div><h2>Locations rendues</h2><p>Archives consultables · exclues des totaux, dépôts et répartitions</p></div><span class="pill neutral">${archived.length}</span></div><div class="table-wrap"><table class="fleet-table rental-table"><thead><tr><th>IMMATRICULATION</th><th>VÉHICULE</th><th>ACTIVITÉ</th><th>DÉPÔT AU RETOUR</th><th>LOUEUR</th><th>PRIX / LOCATION</th><th>ENTRÉE</th><th>DATE DE RETOUR</th><th>ÉTAT</th></tr></thead><tbody>${archived.length?archived.map(r=>rowHtml(r,true)).join(''):'<tr><td colspan="9" class="empty-state">Aucune location rendue archivée.</td></tr>'}</tbody></table></div></section><div class="table-footer">Le champ « sortie prévue » reste informatif. Seule l’action « Rendre » déplace une location active vers les archives.</div>`}
function rentalDetailPage(){let r=db.rentals.find(x=>x.id===selected)||(db.rentalsArchive||[]).find(x=>x.id===selected);if(!r){page='rentals';return rentalsPage()}let returned=!!r.returnDate,caution=r.caution?'Oui':'Non';return `<div class="page-head"><div><button class="link-button" id="back-to-rentals">← Locations</button><h1 style="margin-top:10px">Fiche location</h1><p>${returned?'Location rendue · archive':'Location active'}</p></div><div class="head-actions">${!returned&&canEdit()?`<button class="btn primary" data-return-rental="${escapeAttr(r.id)}">Rendre</button><button class="btn light" data-edit-rental="${escapeAttr(r.id)}">✎ Modifier</button>`:''}${returned?'<span class="pill neutral">RENDUE</span>':''}</div></div><div class="rental-detail-hero"><span class="plate">${esc(r.plate||'—')}</span><span class="status">${pill(returned?'RENDUE':'LOCATION',returned?'neutral':'blue')}</span><h2>${esc([r.brand,r.model].filter(Boolean).join(' ')||'—')}</h2><p>${esc(r.activity||'')}</p><div class="hero-bottom"><span>Loueur · ${esc(r.lessor||'—')}</span><span>Dépôt · ${esc(r.depot||'—')}</span><span>Prix · ${fmtNum(r.price)} €</span><span>Entrée · ${fmtDate(r.entryDate)}</span><span>Caution · ${caution}${r.caution&&r.cautionAmount!=null?` · ${fmtNum(r.cautionAmount)} €`:''}</span></div></div>`}
function returnRentalModal(id){if(!canEdit())return toast('Action réservée aux profils Responsable et RH.');let r=db.rentals.find(x=>x.id===id);if(!r)return;openModal('Rendre une location',`<p class="form-note">La location sera déplacée dans « Locations rendues » et retirée immédiatement des totaux du parc et des dépôts.</p><form id="return-rental-form" class="form-grid"><label class="full">Date de retour<input name="returnDate" type="date" value="${currentDate()}" required></label></form>`,`<button class="btn light" data-close>Annuler</button><button class="btn primary" id="confirm-return-rental">Confirmer le retour</button>`);$('#confirm-return-rental').onclick=()=>{let date=$('#return-rental-form').elements.returnDate.value;if(!date)return toast('Choisissez une date de retour.');if(r.entryDate&&date<r.entryDate)return toast('La date de retour ne peut pas précéder la date d’entrée.');db.rentals=db.rentals.filter(x=>x.id!==id);db.rentalsArchive=db.rentalsArchive||[];db.rentalsArchive.push({...r,returnDate:date});save();closeModal();render();toast('Location rendue et déplacée dans les archives.')};}
function transferRentalModal(id){if(!canEdit())return toast('Modification réservée aux profils Responsable et RH.');let r=db.rentals.find(x=>x.id===id);if(!r)return;let destinations=db.depots.filter(d=>d!==r.depot);openModal('Transférer la location',`<form id="transfer-rental-form" class="form-grid"><label>Dépôt actuel<input value="${escapeAttr(r.depot||'—')}" disabled></label><label>Dépôt d’arrivée<select name="to" required><option value="">Choisir…</option>${destinations.map(d=>`<option value="${escapeAttr(d)}">${esc(d)}</option>`).join('')}</select></label><label class="full">Date du transfert<input type="date" name="date" value="${currentDate()}" required></label></form>`,`<button class="btn light" data-close>Annuler</button><button class="btn primary" id="save-rental-transfer">Transférer</button>`);$('#save-rental-transfer').onclick=()=>{let f=new FormData($('#transfer-rental-form')),to=String(f.get('to')||''),date=String(f.get('date')||'');if(!db.depots.includes(to)||to===r.depot)return toast('Choisissez un autre dépôt valide.');r.transferHistory=Array.isArray(r.transferHistory)?r.transferHistory:[];r.transferHistory.push({date,from:r.depot||'',to});r.depot=to;save();closeModal();render();toast(`Location transférée vers ${to}.`)}}
function rentalModal(r,depot){if(!canEdit())return toast('Modification réservée aux profils Responsable et RH.');let edit=!!r, brands=rentalValues('brand'), lessors=rentalValues('lessor'), plate=r?.plate||'', other=(value,values)=>!!value&&!values.some(x=>keyText(x)===keyText(value));let brandOther=other(r?.brand||'',brands),lessorOther=other(r?.lessor||'',lessors);const options=(xs,v)=>xs.map(x=>`<option value="${escapeAttr(x)}" ${keyText(x)===keyText(v)?'selected':''}>${esc(x)}</option>`).join('');let body=`<form id="rental-form" class="form-grid"><p id="rental-error" role="alert" aria-live="polite" class="full" style="display:none;color:#a33;margin:0"></p><label>Immatriculation<input name="plate" required maxlength="12" placeholder="AA-123-BB" value="${escapeAttr(plate)}" ${edit?'readonly':''}></label><label>Activité<select name="activity" required><option value="">Choisir…</option><option ${r?.activity==='NEXTDAY'?'selected':''}>NEXTDAY</option><option ${r?.activity==='SAMEDAY'?'selected':''}>SAMEDAY</option></select></label><label>Dépôt<select name="depot" required><option value="">Choisir…</option>${db.depots.map(d=>`<option value="${escapeAttr(d)}" ${((r?.depot??depot??'')===d)?'selected':''}>${esc(d)}</option>`).join('')}</select></label><label>Marque<select name="brandChoice" id="rental-brand" required><option value="">Choisir…</option>${options(brands,brandOther?'':r?.brand||'')}<option value="__OTHER__" ${brandOther?'selected':''}>Autre…</option></select><input id="rental-brand-other" type="text" placeholder="Saisir une marque" value="${escapeAttr(brandOther?r?.brand:'')}" style="display:${brandOther?'block':'none'};margin-top:6px"></label><label>Modèle<select name="modelChoice" id="rental-model" required></select><input id="rental-model-other" type="text" placeholder="Saisir un modèle" value="" style="display:none;margin-top:6px"></label><label>Loueur<select name="lessorChoice" id="rental-lessor" required><option value="">Choisir…</option>${options(lessors,lessorOther?'':r?.lessor||'')}<option value="__OTHER__" ${lessorOther?'selected':''}>Autre…</option></select><input id="rental-lessor-other" type="text" placeholder="Saisir un loueur" value="${escapeAttr(lessorOther?r?.lessor:'')}" style="display:${lessorOther?'block':'none'};margin-top:6px"></label><label>Prix (location) · €<input name="price" type="number" min="0" step="0.01" required value="${escapeAttr(r?.price??'')}"></label><label>Date d’entrée<input name="entryDate" type="date" required value="${escapeAttr(r?.entryDate||'')}"></label><label class="rental-deposit-check"><span>Caution</span><span class="rental-check-line"><input name="caution" type="checkbox" value="oui" ${r?.caution?'checked':''}> Oui</span><small>Non si la case reste décochée</small></label><label id="rental-deposit-amount-wrap" style="display:${r?.caution?'block':'none'}">Montant de la caution · € (facultatif)<input name="cautionAmount" type="number" min="0" step="0.01" value="${escapeAttr(r?.cautionAmount??'')}"></label><label>Date de sortie<input name="exitDate" type="date" value="${escapeAttr(r?.exitDate||'')}"></label><label class="full">Commentaire (facultatif)<textarea name="comment">${esc(r?.comment||'')}</textarea></label></form>`;openModal(edit?'Modifier une location':'Nouvelle location',body,`<button class="btn light" data-close>Annuler</button><button class="btn primary" id="save-rental">${edit?'Enregistrer':'Ajouter la location'}</button>`);let brandSel=$('#rental-brand'),brandOtherInput=$('#rental-brand-other'),modelSel=$('#rental-model'),modelOtherInput=$('#rental-model-other');function modelsFor(brand){return [...new Set([...db.vehicles,...db.rentals].filter(x=>keyText(x.brand)===keyText(brand)).map(x=>String(x.model||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr',{sensitivity:'base'}))}function fillModels(){let brand=brandSel.value==='__OTHER__'?brandOtherInput.value:brandSel.value,values=modelsFor(brand),current=r?.model||'',isOther=other(current,values);modelSel.innerHTML='<option value="">Choisir…</option>'+options(values,isOther?'':current)+'<option value="__OTHER__" '+(isOther?'selected':'')+'>Autre…</option>';modelSel.disabled=!String(brand).trim();modelOtherInput.value=isOther?current:'';modelOtherInput.style.display=modelSel.value==='__OTHER__'?'block':'none'}brandSel.onchange=()=>{brandOtherInput.style.display=brandSel.value==='__OTHER__'?'block':'none';fillModels()};brandOtherInput.oninput=fillModels;modelSel.onchange=()=>{modelOtherInput.style.display=modelSel.value==='__OTHER__'?'block':'none'};$('#rental-lessor').onchange=e=>$('#rental-lessor-other').style.display=e.target.value==='__OTHER__'?'block':'none';fillModels();const depositCheck=$('#rental-form').elements.caution,depositAmount=$('#rental-form').elements.cautionAmount;depositCheck.onchange=()=>{$('#rental-deposit-amount-wrap').style.display=depositCheck.checked?'block':'none';if(!depositCheck.checked)depositAmount.value=''};$('#save-rental').onclick=()=>{let form=$('#rental-form');if(!form.reportValidity())return;let f=Object.fromEntries(new FormData(form).entries()),brand=brandSel.value==='__OTHER__'?brandOtherInput.value.trim():brandSel.value,model=modelSel.value==='__OTHER__'?modelOtherInput.value.trim():modelSel.value,lessor=$('#rental-lessor').value==='__OTHER__'?$('#rental-lessor-other').value.trim():$('#rental-lessor').value,normalized=f.plate.toUpperCase().replace(/[\s-]/g,'');if(!/^[A-Z]{2}\d{3}[A-Z]{2}$/.test(normalized))return rentalError('Immatriculation invalide : utilisez le format AA-123-BB.');f.plate=normalized.slice(0,2)+'-'+normalized.slice(2,5)+'-'+normalized.slice(5);if(!brand||!model||!lessor)return rentalError('Renseignez la marque, le modèle et le loueur.');f.price=Number(f.price);if(!Number.isFinite(f.price)||f.price<0)return rentalError('Vérifiez le prix de la location.');f.caution=depositCheck.checked;f.cautionAmount=f.caution&&String(f.cautionAmount||'').trim()!==''?Number(f.cautionAmount):null;if(f.cautionAmount!=null&&(!Number.isFinite(f.cautionAmount)||f.cautionAmount<0))return rentalError('Vérifiez le montant de la caution.');if(f.exitDate&&f.exitDate<f.entryDate)return rentalError('La date de sortie ne peut pas précéder la date d’entrée.');if([...db.vehicles,...db.rentals.filter(x=>x!==r)].some(x=>String(x.plate).toUpperCase()===f.plate))return rentalError('Cette immatriculation existe déjà dans le parc.');f.brand=brand;f.model=model;f.lessor=lessor;delete f.brandChoice;delete f.modelChoice;delete f.lessorChoice;f.comment=String(f.comment||'').trim();upsertRental(f,r?.id);closeModal();render();toast(edit?'Location mise à jour.':'Location ajoutée.')};function rentalError(message){$('#rental-error').textContent=message;$('#rental-error').style.display='block';toast(message)}}
function upsertRental(data,id){let record={...data,id:id||`location-${Date.now()}-${Math.random().toString(36).slice(2,8)}`};if(id){let i=db.rentals.findIndex(x=>x.id===id);if(i<0)throw Error('Location introuvable');db.rentals[i]=record}else db.rentals.push(record);save();return record}
function deleteRental(id){if(!canEdit())return toast('Suppression réservée aux profils Responsable/RH.');let r=db.rentals.find(x=>x.id===id);if(!r||!confirm(`Supprimer la location de ${r.plate} ?`))return;db.rentals=db.rentals.filter(x=>x.id!==id);save();render();toast('Location supprimée.')}
function archivePage(){let vs=db.vehicles.filter(v=>v.ownership!=='LOCATION'&&v.status==='sorti'&&(!filters.reason||(filters.reason==='__empty__'?(!v.exitReason||v.exitReason==='À préciser'):v.exitReason===filters.reason)));return `<div class="page-head"><div><span class="eyebrow kicker">HISTORIQUE / NON SUPPRIMÉS</span><h1>Sortis de flotte</h1><p>${vs.length} véhicule${vs.length===1?'':'s'} archivé${vs.length===1?'':'s'}.</p></div><div class="head-actions"><button class="btn light" id="backup-export">⇩ Sauvegarde complète</button><button class="btn light" id="export-archive">⇩ CSV archives</button><button class="btn light" id="backup-import-button">⇧ Restaurer</button><input type="file" id="backup-file" accept="application/json,.json" hidden></div></div><div class="archive-banner">Les véhicules sortis sont conservés. Les six anciennes sorties sont marquées « À préciser » sans motif inventé; ouvrez leur fiche pour compléter.</div><div class="filterbar"><select id="filter-reason"><option value="">Toutes les raisons</option><option value="__empty__" ${filters.reason==='__empty__'?'selected':''}>Sans raison</option><option value="À préciser" ${filters.reason==='À préciser'?'selected':''}>À préciser — à compléter</option>${EXIT_REASONS.filter(r=>r!=='À préciser').map(r=>`<option ${filters.reason===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="table-wrap"><table class="fleet-table"><thead><tr><th>IMMATRICULATION</th><th>VÉHICULE / CARACTÉRISTIQUES</th><th>DATE DE SORTIE</th><th>RAISON</th><th>HISTORIQUE</th><th>STATUT</th></tr></thead><tbody>${vs.length?vs.map(v=>`<tr data-plate="${escapeAttr(v.plate)}"><td class="plate">${esc(v.plate)}</td><td class="vehicle-model"><b>${esc(v.brand||'—')} ${esc(v.model||'')}</b><small>${esc(v.version||'')}${v.power?` · ${v.power} CV`:''}</small></td><td>${fmtDate(v.exitDate)}</td><td>${v.exitReason==='À préciser'?pill('À PRÉCISER — à compléter','bad'):v.exitReason?pill(v.exitReason,'warn'):pill('À renseigner','bad')}${v.exitReasonDetail||v.exitComment?`<small style="display:block;margin-top:4px">${esc([v.exitReasonDetail,v.exitComment].filter(Boolean).join(' · '))}</small>`:''}</td><td>${v.kmHistory.length} km · ${v.repairs.length} répar.</td><td>${pill('Sorti','neutral')}</td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">Aucun véhicule archivé pour ce filtre.</td></tr>'}</tbody></table></div><div class="table-footer">Sauvegarde locale : exportez régulièrement un fichier JSON pour conserver les documents et modifications.</div>`}
function detailPage(){let v=db.vehicles.find(x=>x.plate===selected);if(!v){page='vehicles';return vehiclesPage()}let arch=v.status==='sorti';let ct=stateDate(ctDateFor(v)),ol=oilState(v),insuranceDoc=docIndex[docId(v.plate,'Assurance')],kmNotice=v.status==='actif'&&v.condition!=='HS'?kmAlert(v):null;let km=[...v.kmHistory].sort((a,b)=>b.date.localeCompare(a.date)),oils=[...v.oilHistory].sort((a,b)=>b.date.localeCompare(a.date)),rep=[...v.repairs].sort((a,b)=>(b.date||'').localeCompare(a.date||'')),pannes=[...(v.pannes||[])].sort((a,b)=>(b.date||'').localeCompare(a.date||'')),transfers=[...(v.transferHistory||[])].sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `<div class="page-head"><div><button class="link-button" id="back-to-list">← ${arch?'Archives':'Véhicules'}</button><h1 style="margin-top:10px">Fiche véhicule</h1><p>${arch?'Archive / statut sorti':'Données du véhicule et entretiens enregistrés'}</p>${arch?`<div class="exit-highlight">${v.exitReason==='À préciser'?`À PRÉCISER — compléter le motif · ${fmtDate(v.exitDate)}`:v.exitReason?`Sortie : ${esc(v.exitReason)}${v.exitReasonDetail?' · '+esc(v.exitReasonDetail):''}${v.exitComment?' · '+esc(v.exitComment):''} · ${fmtDate(v.exitDate)}`:'À RENSEIGNER · raison de sortie inconnue'}</div>`:''}</div><div class="head-actions">${!arch?'<button class="btn light" id="transfer-vehicle">⇄ Transférer</button>':''}${!arch?'<button class="btn light" id="report-breakdown">⚑ Signaler une panne</button>':''}${!arch&&canEdit()?'<button class="btn danger" id="archive-vehicle">Archiver</button>':''}${arch&&canEdit()?'<button class="btn light" id="reactivate-vehicle">Réactiver</button>':''}${arch&&canEdit()?'<button class="btn light" id="edit-exit">✎ Motif de sortie</button>':''}${canEdit()?`<button class="btn light" id="edit-vehicle">✎ Modifier</button>`:''}<button class="btn light" id="export-one">⇩</button></div></div>${kmNotice?`<div class="alert-row" role="status" style="background:#fff2dc;border:1px solid #f0dfbd;border-radius:9px;padding:12px 16px;margin-bottom:16px;grid-template-columns:28px 1fr;cursor:default"><span class="alert-symbol">↻</span><div class="alert-copy"><b>${esc(kmNotice.detail)}</b></div></div>`:''}<div class="vehicle-summary"><section class="vehicle-hero"><span class="plate">${esc(v.plate)}</span><span class="status">${pill(arch?'SORTI':v.condition,v.condition==='HS'?'bad':arch?'neutral':'')}</span><h2>${esc([v.brand,v.model,v.version].filter(Boolean).join(' ')||'—')}</h2><p>${v.year?`Année ${v.year}`:'Année non renseignée'}</p><div class="hero-bottom"><span>${esc(v.activity||'ARCHIVE')}</span><span>${esc(v.company||'Société n/r')}</span><span>${fmtNum(v.km)} KM</span><span>${v.power!=null?`${fmtNum(v.power)} CV`:'Puissance n/r'}</span><span>${v.prixAchat!=null?`${fmtNum(v.prixAchat)} €`:'Prix n/r'}</span><span>${v.dateAcquisition?`Acquis le ${fmtDate(v.dateAcquisition)}`:'Acquisition n/r'}</span></div></section><section class="panel"><div class="panel-head"><div><h2>Échéances</h2><p>État connu depuis les données disponibles</p></div></div><div class="alert-list"><div class="alert-row"><span class="alert-symbol ${ct.kind==='bad'?'red':''}">◷</span><div class="alert-copy"><b>Contrôle technique</b><small>${fmtDate(ctDateFor(v))}</small></div>${pill(ct.label,ct.kind)}</div><div class="alert-row"><span class="alert-symbol ${ol.kind==='bad'?'red':''}">⚙</span><div class="alert-copy"><b>Prochaine vidange</b><small>${fmtNum(nextOil(v))} km</small></div>${pill(ol.label,ol.kind==='good'?'':ol.kind)}</div><div class="alert-row"><span class="alert-symbol">⌁</span><div class="alert-copy"><b>Assurance</b><small>${esc(v.insurer||'Assureur non renseigné')}</small></div>${pill(insuranceDoc?'À jour':'Manquante',insuranceDoc?'good':'warn')}</div></div></section></div><section class="detail-section docs-section"><div class="docs-heading"><div><h3>Documents</h3><p>Les fichiers restent stockés sur cet appareil dans ce navigateur.</p></div><button class="btn light small" id="quick-docs-detail">Gérer les documents</button></div><div class="doc-type-grid">${DOC_TYPES.map(t=>docCard(v,t)).join('')}</div></section><div class="detail-grid"><section class="detail-section"><h3>Informations générales</h3>${[['Activité',v.activity],['Société propriétaire',v.company],['Dépôt',v.depot||'À affecter'],['Achat / location',v.ownership],['Situation carte grise',v.cgStatus],['Assureur',v.insurer],['Puissance (CV)',v.power==null?null:`${fmtNum(v.power)} CV`],['Prix d’achat',v.prixAchat==null?null:fmtNum(v.prixAchat)+' €'],['Date d’acquisition',v.dateAcquisition?fmtDate(v.dateAcquisition):null],...(String(v.comment||'').trim()?[['Commentaire',v.comment]]:[])].map(([k,val])=>`<div class="detail-item"><span>${k}</span><span>${val?String(val).startsWith('<a')?val:esc(val):'—'}</span></div>`).join('')}</section><section class="detail-section"><h3>Compteurs & caractéristiques</h3>${[['Kilométrage actuel',v.km==null?null:fmtNum(v.km)+' km'],['Dernière vidange',v.oilLast==null?null:fmtNum(v.oilLast)+' km'],['Prochaine vidange',nextOil(v)==null?null:fmtNum(nextOil(v))+' km']].map(([k,val])=>`<div class="detail-item"><span>${k}</span><span>${val||'—'}</span></div>`).join('')}<div style="margin-top:13px">${!arch?'<button class="btn primary small" id="add-km">＋ Saisir un kilométrage</button>':''}${!arch&&canManageMaintenance()?'<button class="btn light small" id="add-oil">＋ Enregistrer une vidange</button>':''}${role==='chef'?'<p class="form-note">Accès Chef : enregistrement/suppression permis sur tous les véhicules visibles. Aucun lien profil–dépôt exploitable dans ce prototype.</p>':''}</div></section><section class="detail-section"><h3>Historique kilométrique <span class="muted" style="font:10px 'DM Sans'">${km.length} relevés importés</span></h3><div class="history-list">${km.length?km.map(h=>{let index=v.kmHistory.indexOf(h);return `<div class="history-row"><time>${fmtDate(h.date)}</time><b>${fmtNum(h.km)} km</b>${canManageMaintenance()?`<button class="btn danger small" data-delete-km="${index}" aria-label="Supprimer le relevé kilométrique du ${fmtDate(h.date)}">Supprimer</button>`:''}</div>`}).join(''):'<div class="empty-state">Aucun relevé de compteur disponible.</div>'}</div></section><section class="detail-section transfer-history"><div class="transfer-history-head"><h3>Historique des transferts <span class="muted" style="font:10px 'DM Sans'">${transfers.length}</span></h3><button class="btn primary small" id="transfer-vehicle-history">＋ Transférer</button></div><div class="history-list">${transfers.length?transfers.map(t=>`<div class="history-row transfer-row"><time>${fmtDate(t.date)}</time><span class="transfer-route"><b>${esc(t.from||'À affecter')}</b><i>→</i><b>${esc(t.to||'À affecter')}</b></span><button class="btn danger small" data-delete-transfer="${escapeAttr(t.id||v.transferHistory.indexOf(t))}" aria-label="Supprimer le transfert du ${fmtDate(t.date)}">Supprimer</button></div>`).join(''):'<div class="empty-state">Aucun transfert enregistré.</div>'}</div></section><section class="detail-section"><h3>Historique des vidanges <span class="muted" style="font:10px 'DM Sans'">${oils.length} relevés importés</span></h3><div class="history-list">${oils.length?oils.map(h=>{let index=v.oilHistory.indexOf(h);return `<div class="history-row"><time>${fmtDate(h.date)}</time><b>${fmtNum(h.km)} km</b>${canManageMaintenance()?`<button class="btn danger small" data-delete-oil="${index}" aria-label="Supprimer la vidange du ${fmtDate(h.date)}">Supprimer</button>`:''}</div>`}).join(''):'<div class="empty-state">Aucun historique de vidange renseigné.</div>'}</div></section><section class="detail-section" style="grid-column:1/-1"><div style="display:flex;align-items:center;justify-content:space-between"><h3>Historique des pannes <span class="muted" style="font:10px 'DM Sans'">${pannes.length}</span></h3></div><div class="table-wrap"><table class="fleet-table breakdown-history-table" style="min-width:680px"><thead><tr><th>DATE DE DÉCLARATION</th><th>DESCRIPTION</th><th>TYPE / ORIGINE</th><th>PHOTO</th><th>STATUT</th><th>DATE DE RÉPARATION</th><th>INTERVENTION LIÉE</th></tr></thead><tbody>${pannes.length?pannes.map(p=>{let intervention=rep.find(r=>r.id===p.interventionId||r.panneId===p.id);return `<tr><td>${fmtDate(p.date)}</td><td style="white-space:normal;min-width:170px">${esc(p.description||'—')}</td><td>${p.typePanne?`${pill(p.typePanne,p.typePanne==='Casse'?'warn':'blue')}${p.typePanne==='Casse'&&p.origineCasse?`<small style="display:block;margin-top:4px">Origine : ${esc(p.origineCasse)}${p.responsable?` — ${esc(p.responsable)}`:''}</small>`:''}`:'—'}</td><td>${p.photo?String(p.photo).startsWith('data:')?`<a href="${p.photo}" target="_blank" rel="noopener">Voir</a>`:`<button class="link-button" data-panne-photo="${escapeAttr(p.photo)}">Voir</button>`:'—'}</td><td>${pill(p.status||'En cours',p.status==='Réparée'?'good':'warn')}</td><td>${fmtDate(p.dateReparation)}</td><td>${intervention?`${fmtDate(intervention.date)} · ${esc(intervention.work||'Intervention')}`:'—'}</td></tr>`}).join(''):'<tr><td colspan="7" class="empty-state">Aucune panne renseignée.</td></tr>'}</tbody></table></div></section><section class="detail-section" style="grid-column:1/-1"><div style="display:flex;align-items:center;justify-content:space-between"><h3>Registre des réparations <span class="muted" style="font:10px 'DM Sans'">${rep.length} lignes source</span></h3>${canEdit()?'<button class="btn light small" id="add-repair">＋ Intervention</button>':''}</div><div class="table-wrap"><table class="fleet-table repair-history-table" style="min-width:680px"><thead><tr><th>DATE</th><th>TYPE / TRAVAUX</th><th>INTERVENANT</th><th>PIÈCES</th><th>MAIN D’ŒUVRE</th><th>TOTAL</th><th>PANNE LIÉE</th></tr></thead><tbody>${rep.length?rep.map(r=>`<tr><td>${fmtDate(r.date)}</td><td>${pill(r.type,'blue')}<span style="margin-left:6px">${esc(r.work)}</span></td><td>${esc(r.provider||'—')}</td><td>${r.parts==null?'—':fmtNum(r.parts)+' €'}</td><td>${r.labor==null?'—':fmtNum(r.labor)+' €'}</td><td><b>${r.total==null?'—':fmtNum(r.total)+' €'}</b></td><td>${r.panneId?esc((v.pannes||[]).find(p=>p.id===r.panneId)?.description||'Panne'):'—'}</td></tr>`).join(''):'<tr><td colspan="7" class="empty-state">Aucune réparation renseignée.</td></tr>'}</tbody></table></div></section></div>`}
function docCard(v,type){let d=docIndex[docId(v.plate,type)],label=type==='Assurance'?"Attestation d'assurance":type;return `<article class="doc-card"><div class="doc-card-top"><span class="doc-state ${d?'yes':'no'}">${d?'● Présent':'○ Manquant'}</span>${d?`<small>Ajouté ${fmtDate(d.addedDate)}${type!=='Assurance'&&d.expiryDate?` · échéance ${fmtDate(d.expiryDate)}`:''}</small>`:''}</div><strong>${type==='Autre'?(d?.label||'Autre (à préciser)'):label}</strong>${type==='Autre'?`<label class="expiry-label">Nom du document<input type="text" data-doc-label value="${escapeAttr(d?.label||'')}" placeholder="Ex. carte carburant" ${canEdit()?'':'disabled'}></label>`:''}${type==='Contrôle technique'?`<label class="expiry-label">Date d’échéance (facultative)<input type="date" data-expiry="${escapeAttr(type)}" value="${escapeAttr(d?.expiryDate||'')}" ${canEdit()?'':'disabled'}></label>`:''}${d?`<div class="doc-file">${esc(d.name)}</div><div class="doc-actions"><button class="btn light small" data-doc-open="${escapeAttr(docId(v.plate,type))}">Ouvrir</button><button class="btn light small" data-doc-download="${escapeAttr(docId(v.plate,type))}">Télécharger</button>${canEdit()?`<label class="btn light small file-pick">Remplacer<input type="file" data-doc-upload="${escapeAttr(type)}" accept="application/pdf,image/*" capture="environment"></label>`:''}${canEdit()?`<button class="btn danger small" data-doc-delete="${escapeAttr(docId(v.plate,type))}">Supprimer</button>`:''}</div>`:canEdit()?`<label class="btn primary small file-pick">＋ Ajouter<input type="file" data-doc-upload="${escapeAttr(type)}" accept="application/pdf,image/*" capture="environment"></label>`:`<small class="muted">Ajout réservé Responsable / RH</small>`}</article>`}
function openDocuments(plate){selected=plate;let v=db.vehicles.find(x=>x.plate===plate);if(!v)return;openModal(`Documents · ${plate}`,`<p class="storage-note">Stockage local à cet appareil uniquement. Exportez une sauvegarde JSON pour garder les fichiers; ils ne sont pas envoyés au cloud.</p><div class="doc-type-grid">${DOC_TYPES.map(t=>docCard(v,t)).join('')}</div>`,`<button class="btn light" data-close>Fermer</button>`);bindDocumentControls()}
function bindDocumentControls(){document.querySelectorAll('[data-expiry]').forEach(inp=>inp.onchange=async()=>{let id=docId(selected,inp.dataset.expiry),d=docIndex[id],v=db.vehicles.find(x=>x.plate===selected);if(d){d.expiryDate=inp.value;await saveDocument(d);await refreshDocIndex()}toast('Échéance mise à jour.');if(!$('#modal-root').innerHTML)render();else openDocuments(selected)});document.querySelectorAll('[data-doc-label]').forEach(inp=>inp.onchange=async()=>{if(!canEdit())return;let d=docIndex[docId(selected,'Autre')];if(d){d.label=inp.value.trim();await saveDocument(d);await refreshDocIndex();openDocuments(selected)}});document.querySelectorAll('[data-doc-upload]').forEach(inp=>inp.onchange=async e=>{let f=e.target.files?.[0];if(!f)return;if(!canEdit()){toast('Ajout réservé aux profils Responsable/RH.');return}let type=inp.dataset.docUpload;if(!/^application\/pdf$|^image\//i.test(f.type)){toast('Choisissez un PDF ou une image.');return}try{let file=await compressImage(f);if(file.size>25*1024*1024)throw Error('too-large');let record={id:docId(selected,type),plate:selected,type,label:type==='Autre'?($('[data-doc-label]')?.value.trim()||''): '',name:file.name,mime:file.type,addedDate:currentDate(),expiryDate:'',blob:file};let old=docIndex[record.id];record.expiryDate=type==='Contrôle technique'?($(`[data-expiry="${CSS.escape(type)}"]`)?.value||old?.expiryDate||''):'';await saveDocument(record);await refreshDocIndex();toast('Document enregistré localement.');openDocuments(selected)}catch(err){toast(err?.message==='too-large'?'Fichier trop volumineux (maximum 25 Mo).':'Échec du stockage du document. Vérifiez l’espace disponible.')}});document.querySelectorAll('[data-doc-open]').forEach(b=>b.onclick=async()=>{let w=window.open('about:blank','_blank');let d=await getDocument(b.dataset.docOpen);if(d&&w){let u=URL.createObjectURL(d.blob);w.location.href=u;setTimeout(()=>URL.revokeObjectURL(u),60000)}else if(w)w.close()});document.querySelectorAll('[data-doc-download]').forEach(b=>b.onclick=async()=>{let d=await getDocument(b.dataset.docDownload);if(d){let a=document.createElement('a');a.href=URL.createObjectURL(d.blob);a.download=d.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000)}});document.querySelectorAll('[data-doc-delete]').forEach(b=>b.onclick=async()=>{if(!canEdit())return toast('Suppression réservée Responsable/RH.');if(!confirm('Supprimer ce document de cet appareil ?'))return;await deleteDocument(b.dataset.docDelete);await refreshDocIndex();openDocuments(selected);toast('Document supprimé.')});}
function exitModal(v,archive){if(!canEdit())return toast('Action réservée aux profils Responsable et RH.');openModal(archive?'Archiver le véhicule':'Modifier la raison de sortie',`<p class="form-note">Une raison doit être choisie avant l’archivage. Pour les anciennes sorties, « À préciser » permet de renseigner le motif plus tard.</p><form id="exit-form" class="form-grid"><label>Raison de sortie<select name="exitReason"><option value="">${archive?'Choisir une raison…':'À renseigner'}</option>${EXIT_REASONS.filter(r=>!archive||r!=='À préciser').map(r=>`<option ${v.exitReason===r?'selected':''}>${r}</option>`).join('')}</select></label><label>Date de sortie<input type="date" name="exitDate" value="${v.exitDate||(archive?currentDate():'')}"></label><label class="full">Précision (obligatoire si « Autre »)<input name="exitReasonDetail" value="${escapeAttr(v.exitReasonDetail||'')}" placeholder="Précisez la raison « Autre »"></label><label class="full">Commentaire (facultatif)<textarea name="exitComment">${esc(v.exitComment||'')}</textarea></label></form>`,`<button class="btn light" data-close>Annuler</button><button class="btn primary" id="save-exit">${archive?'Archiver':'Enregistrer'}</button>`);$('#save-exit').onclick=()=>{let o=Object.fromEntries(new FormData($('#exit-form')).entries());if(archive&&!o.exitReason)return toast('Choisissez obligatoirement une raison de sortie.');if(o.exitReason==='Autre'&&!o.exitReasonDetail.trim())return toast('Précisez la raison « Autre ».');Object.assign(v,o);if(archive)v.status='sorti';save();closeModal();render();toast(archive?'Véhicule archivé.':'Motif de sortie enregistré.')};}
async function backupExport(){try{let docs=await new Promise((resolve,reject)=>{let r=docDB.transaction('docs').objectStore('docs').getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)});let encoded=[];for(let d of docs){let bytes=new Uint8Array(await d.blob.arrayBuffer()),parts=[];for(let i=0;i<bytes.length;i+=0x8000)parts.push(String.fromCharCode(...bytes.subarray(i,i+0x8000)));encoded.push({...d,blob:undefined,data:btoa(parts.join(''))})}let data={format:'atelier-flotte-backup-v1',exportedAt:new Date().toISOString(),db,documents:encoded};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));a.download='sauvegarde-flotte.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000);toast('Sauvegarde JSON téléchargée.')}catch(e){toast('Impossible de préparer la sauvegarde.') }}
async function backupImport(file){if(!file)return;if(!canEdit()){toast('Restauration réservée aux profils Responsable/RH.');return}try{let x=JSON.parse(await file.text());if(x.format!=='atelier-flotte-backup-v1'||!Array.isArray(x.db?.vehicles)||!Array.isArray(x.documents))throw Error('format');if(!confirm('Restaurer cette sauvegarde remplacera les données locales actuelles. Continuer ?'))return;migrateDb(x.db);save();await new Promise((resolve,reject)=>{let r=docDB.transaction('docs','readwrite').objectStore('docs').clear();r.onsuccess=resolve;r.onerror=()=>reject(r.error)});for(const d of x.documents){let bytes=Uint8Array.from(atob(d.data),c=>c.charCodeAt(0));await saveDocument({...d,blob:new Blob([bytes],{type:d.mime||'application/octet-stream'})})}await refreshDocIndex();toast('Sauvegarde restaurée.');render()}catch(e){toast('Fichier invalide ou sauvegarde illisible.')}}
