 document.querySelectorAll('[data-doc-open]').forEach(b=>b.onclick=async e=>{e.stopPropagation();let w=window.open('about:blank','_blank'),d=await getDocument(b.dataset.docOpen);if(d&&w)w.location.href=URL.createObjectURL(d.blob);else if(w)w.close()});
