 document.querySelectorAll('[data-doc-delete]').forEach(b=>b.onclick=async e=>{e.stopPropagation();if(!canEdit())return toast('Suppression réservée Responsable/RH.');if(confirm('Supprimer ce document de cet appareil ?')){await deleteDocument(b.dataset.docDelete);await refreshDocIndex();render();toast('Document supprimé.')}});
